package com.spaceagent.platform.inference.infrastructure.persistence;

import com.spaceagent.platform.inference.domain.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import org.springframework.transaction.*;import org.springframework.transaction.support.TransactionTemplate;
import java.sql.*;import java.time.*;import java.util.*;
@Repository @ConditionalOnProperty(prefix="platform",name="persistence",havingValue="postgres")
public class PostgresInferenceBudgetRepository implements InferenceBudgetRepository{
 private static final String C="id::text,tenant_id,agent_run_id,logical_call_id,provider_id,model_id,price_id::text,input_price_micros_per_million,output_price_micros_per_million,reserved_tokens,reserved_cost_micros,status,actual_input_tokens,actual_output_tokens,actual_cost_micros,created_at,updated_at";private final JdbcTemplate j;private final TransactionTemplate tx;public PostgresInferenceBudgetRepository(JdbcTemplate j,PlatformTransactionManager m){this.j=j;tx=new TransactionTemplate(m);tx.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRES_NEW);}
 public InferenceBudgetPolicy savePolicy(InferenceBudgetPolicy p){return req(tx.execute(x->{j.update("INSERT INTO platform_inference_budget_policies(tenant_id,enabled,monthly_request_limit,monthly_token_limit,monthly_cost_limit_micros,revision,updated_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(tenant_id) DO UPDATE SET enabled=EXCLUDED.enabled,monthly_request_limit=EXCLUDED.monthly_request_limit,monthly_token_limit=EXCLUDED.monthly_token_limit,monthly_cost_limit_micros=EXCLUDED.monthly_cost_limit_micros,revision=platform_inference_budget_policies.revision+1,updated_by=EXCLUDED.updated_by,updated_at=EXCLUDED.updated_at",p.tenantId(),p.enabled(),p.monthlyRequestLimit(),p.monthlyTokenLimit(),p.monthlyCostLimitMicros(),p.revision(),p.updatedBy(),Timestamp.from(p.createdAt()),Timestamp.from(p.updatedAt()));return findPolicy(p.tenantId()).orElseThrow();}));}
 public Optional<InferenceBudgetPolicy> findPolicy(String t){return j.query("SELECT tenant_id,enabled,monthly_request_limit,monthly_token_limit,monthly_cost_limit_micros,revision,updated_by,created_at,updated_at FROM platform_inference_budget_policies WHERE tenant_id=?",(r,n)->new InferenceBudgetPolicy(r.getString(1),r.getBoolean(2),r.getLong(3),r.getLong(4),r.getLong(5),r.getLong(6),r.getString(7),r.getTimestamp(8).toInstant(),r.getTimestamp(9).toInstant()),t).stream().findFirst();}
 public ReservationDecision reserve(ReserveRequest r){return req(tx.execute(x->reserveTx(r)));}
 private ReservationDecision reserveTx(ReserveRequest r){InferenceBudgetReservation existing=j.query("SELECT "+C+" FROM platform_inference_budget_reservations WHERE (agent_run_id=? AND logical_call_id=?) OR embedding_call_id=? FOR UPDATE",this::map,r.agentRunId(),r.logicalCallId(),r.embeddingCallId()).stream().findFirst().orElse(null);if(existing!=null)return new ReservationDecision(existing,false);LocalDate start=j.queryForObject("SELECT date_trunc('month',clock_timestamp())::date",LocalDate.class),end=start.plusMonths(1);j.update("INSERT INTO platform_inference_budget_periods(tenant_id,period_start,period_end,updated_at) VALUES(?,?,?,clock_timestamp()) ON CONFLICT DO NOTHING",r.tenantId(),java.sql.Date.valueOf(start),java.sql.Date.valueOf(end));Period p=j.query("SELECT consumed_requests,reserved_requests,consumed_tokens,reserved_tokens,consumed_cost_micros,reserved_cost_micros FROM platform_inference_budget_periods WHERE tenant_id=? AND period_start=? FOR UPDATE",(rs,n)->new Period(rs.getLong(1),rs.getLong(2),rs.getLong(3),rs.getLong(4),rs.getLong(5),rs.getLong(6)),r.tenantId(),java.sql.Date.valueOf(start)).getFirst();InferenceBudgetPolicy policy=findPolicy(r.tenantId()).orElse(null);if(policy!=null&&policy.enabled()){if(policy.monthlyCostLimitMicros()>0&&r.reservedCostMicros()==null)throw new InferenceBudgetLimitException("INFERENCE_PRICE_REQUIRED");check(policy.monthlyRequestLimit(),p.cr+p.rr+1,"INFERENCE_REQUEST_QUOTA_EXCEEDED");check(policy.monthlyTokenLimit(),p.ct+p.rt+r.reservedTokens(),"INFERENCE_TOKEN_BUDGET_EXCEEDED");check(policy.monthlyCostLimitMicros(),p.cc+p.rc+nvl(r.reservedCostMicros()),"INFERENCE_COST_BUDGET_EXCEEDED");}j.update("UPDATE platform_inference_budget_periods SET reserved_requests=reserved_requests+1,reserved_tokens=reserved_tokens+?,reserved_cost_micros=reserved_cost_micros+?,revision=revision+1,updated_at=clock_timestamp() WHERE tenant_id=? AND period_start=?",r.reservedTokens(),nvl(r.reservedCostMicros()),r.tenantId(),java.sql.Date.valueOf(start));j.update("INSERT INTO platform_inference_budget_reservations(id,tenant_id,agent_run_id,logical_call_id,provider_id,model_id,price_id,input_price_micros_per_million,output_price_micros_per_million,reserved_tokens,reserved_cost_micros,status,period_start,embedding_call_id,created_at,updated_at) VALUES(CAST(? AS UUID),?,?,?,?,?,CAST(? AS UUID),?,?,?,?, 'HELD',?,?,clock_timestamp(),clock_timestamp())",r.id(),r.tenantId(),r.agentRunId(),r.logicalCallId(),r.providerId(),r.modelId(),r.priceId(),r.inputRate(),r.outputRate(),r.reservedTokens(),r.reservedCostMicros(),java.sql.Date.valueOf(start),r.embeddingCallId());return new ReservationDecision(findReservation(r.id(),true).orElseThrow(),true);}
 public Optional<InferenceBudgetReservation> settle(String id,long in,long out){return req(tx.execute(x->{InferenceBudgetReservation v=findReservation(id,true).orElse(null);if(v==null||!v.status().equals("HELD"))return Optional.ofNullable(v);long cost=calc(v,in,out);java.sql.Date period=j.queryForObject("SELECT period_start FROM platform_inference_budget_reservations WHERE id=CAST(? AS UUID)",java.sql.Date.class,id);j.update("UPDATE platform_inference_budget_periods SET reserved_requests=reserved_requests-1,reserved_tokens=reserved_tokens-?,reserved_cost_micros=reserved_cost_micros-?,consumed_requests=consumed_requests+1,consumed_tokens=consumed_tokens+?,consumed_cost_micros=consumed_cost_micros+?,revision=revision+1,updated_at=clock_timestamp() WHERE tenant_id=? AND period_start=?",v.reservedTokens(),nvl(v.reservedCostMicros()),in+out,cost,v.tenantId(),period);j.update("UPDATE platform_inference_budget_reservations SET status='SETTLED',actual_input_tokens=?,actual_output_tokens=?,actual_cost_micros=?,updated_at=clock_timestamp() WHERE id=CAST(? AS UUID) AND status='HELD'",in,out,v.priceId()==null?null:cost,id);j.update("UPDATE platform_model_call_ledger SET budget_reservation_id=CAST(? AS UUID),price_id=CAST(? AS UUID),input_tokens=?,output_tokens=?,cost_micros=?,cost_currency=?,updated_at=clock_timestamp() WHERE agent_run_id=? AND logical_call_id=? AND status='SUCCEEDED'",id,v.priceId(),in,out,v.priceId()==null?null:cost,v.priceId()==null?null:"USD",v.agentRunId(),v.logicalCallId());return findReservation(id,false);}));}
 public void release(String id){tx.executeWithoutResult(x->terminal(id,"RELEASED",true));}public void markUnknown(String id){tx.executeWithoutResult(x->terminal(id,"UNKNOWN",false));}
 private void terminal(String id,String status,boolean release){InferenceBudgetReservation v=findReservation(id,true).orElse(null);if(v==null||!v.status().equals("HELD"))return;if(release){java.sql.Date p=j.queryForObject("SELECT period_start FROM platform_inference_budget_reservations WHERE id=CAST(? AS UUID)",java.sql.Date.class,id);j.update("UPDATE platform_inference_budget_periods SET reserved_requests=reserved_requests-1,reserved_tokens=reserved_tokens-?,reserved_cost_micros=reserved_cost_micros-?,revision=revision+1,updated_at=clock_timestamp() WHERE tenant_id=? AND period_start=?",v.reservedTokens(),nvl(v.reservedCostMicros()),v.tenantId(),p);}j.update("UPDATE platform_inference_budget_reservations SET status=?,updated_at=clock_timestamp() WHERE id=CAST(? AS UUID) AND status='HELD'",status,id);}
 public Optional<InferenceBudgetReservation> findEmbeddingReservation(String id){return j.query("SELECT "+C+" FROM platform_inference_budget_reservations WHERE embedding_call_id=?",this::map,id).stream().findFirst();}
 public BudgetUsage usage(String t){LocalDate start=j.queryForObject("SELECT date_trunc('month',clock_timestamp())::date",LocalDate.class);return j.query("SELECT consumed_requests,reserved_requests,consumed_tokens,reserved_tokens,consumed_cost_micros,reserved_cost_micros FROM platform_inference_budget_periods WHERE tenant_id=? AND period_start=?",(r,n)->new BudgetUsage(r.getLong(1),r.getLong(2),r.getLong(3),r.getLong(4),r.getLong(5),r.getLong(6)),t,java.sql.Date.valueOf(start)).stream().findFirst().orElse(new BudgetUsage(0,0,0,0,0,0));}
 private Optional<InferenceBudgetReservation> findReservation(String id,boolean lock){return j.query("SELECT "+C+" FROM platform_inference_budget_reservations WHERE id=CAST(? AS UUID)"+(lock?" FOR UPDATE":""),this::map,id).stream().findFirst();}private InferenceBudgetReservation map(ResultSet r,int n)throws SQLException{return new InferenceBudgetReservation(r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),(Long)r.getObject(8),(Long)r.getObject(9),r.getLong(10),(Long)r.getObject(11),r.getString(12),(Long)r.getObject(13),(Long)r.getObject(14),(Long)r.getObject(15),r.getTimestamp(16).toInstant(),r.getTimestamp(17).toInstant());}private static long calc(InferenceBudgetReservation v,long in,long out){return v.priceId()==null?0:ceil(in,v.inputPriceMicrosPerMillion())+ceil(out,v.outputPriceMicrosPerMillion());}private static long ceil(long t,long r){return Math.addExact(Math.multiplyExact(t,r),999999)/1000000;}private static long nvl(Long v){return v==null?0:v;}private static void check(long l,long v,String c){if(l>0&&v>l)throw new InferenceBudgetLimitException(c);}private static <T>T req(T v){if(v==null)throw new IllegalStateException("Budget transaction returned no result");return v;}private record Period(long cr,long rr,long ct,long rt,long cc,long rc){}
}
